                if (!text || text === '$2') return;
                const avatarUrl = 'https://zora404.dpdns.org/file/1787589637320_image.png';
                let moodsHtml = '';
                finalEmotions.forEach((emotion, index) => {
                    const theme = getMoodTheme(emotion);
                    moodsHtml += `<span class="soleia-mood mood-${theme}" style="animation: fadeInSoleia 0.4s ease ${index * 50}ms both;">${emotion}</span>`;
                });
                const html = `
                    <div class="soleia-wrapper">
                        <span class="soleia-corner tl"></span><span class="soleia-corner tr"></span>
                        <div class="soleia-avatar" id="soleia-avatar-container">
                            <div class="avatar-ring"></div>
                            <div class="avatar-fallback">☀</div>
                            <img src="${avatarUrl}" alt="索利昂" loading="lazy" onload="this.classList.add('img-loaded'); document.getElementById('soleia-avatar-container').classList.add('has-img');" onerror="this.remove();">
                        </div>
                        <div class="soleia-dialogue">
                            <div class="soleia-name-row">
                                <span class="soleia-name">✧ 索利昂</span>
                                <span class="soleia-title-tag">圣光之神 · 黎明化身</span>
                                <div class="soleia-moods">${moodsHtml}</div>
                            </div>
                            <div class="soleia-text-card"><div class="soleia-text">${text}</div></div>
                            <div class="soleia-footer"><span class="line"></span>☀ ✦ 晨光不熄 ✦ ☀<span class="line r"></span></div>
                        </div>
                    </div>`;
                document.getElementById('main-container').innerHTML = html;
            } catch (error) {
                console.error('[索利昂渲染] 错误:', error);
            }
        }
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', init);
        } else {
            init();
        }
    </script>
